using System.Diagnostics;

class C
{
    void M()
    {
#pragma warning disable 8321 // Unreferenced local function
        [Conditional("hello world")] // 1
        static void local1() { }

        [Conditional("DEBUG")] // 2
        static int local2()
        {
            return 42;
        }

        [Conditional("DEBUG")] // 3
        static void local3(out string s)
        {
            s = "hello";
        }
    }
}

